let profileStep=0;
function graduateProfile(){let p={};try{p=JSON.parse(workspaceLocal.getItem('proof-profile')||'{}')}catch{}return {...p,name:p.name||workspaceLocal.getItem('lp-name')||'',education:p.education||workspaceLocal.getItem('lp-education')||'',portfolio:p.portfolio||workspaceLocal.getItem('lp-portfolio')||''}}
function profileCompletion(){const p=graduateProfile(),fields=['name','email','education','field','role','skills','availability','portfolio'];const done=fields.filter(k=>Boolean(p[k]?.trim())).length;return {done,total:fields.length,percent:Math.round(done/fields.length*100)}}
function profile(){const p=graduateProfile();const value=k=>esc(p[k]||'');const input=(key,label,type='text',placeholder='',required=false)=>`<label class="field">${label}<input name="${key}" ${key==='role'?'data-search-catalog="roles"':''} type="${type}" value="${value(key)}" placeholder="${placeholder}" ${required?'required':''} maxlength="300"></label>`;const select=(key,label,options)=>`<label class="field">${label}<select name="${key}" required><option value="">Choose an option</option>${options.map(o=>`<option ${p[key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
return title('Build a profile. Find your kind of work.','Tell startups what you can contribute and what you want to build next.')+`<div class="profile-identity-top"><section class="profile-preview panel">${typeof profilePhotoEditor==='function'?profilePhotoEditor(p):`<div class="avatar" style="width:58px;height:58px;font-size:18px">${profileInitials(p.name)}</div>`}<h2>${value('name')||'Your name goes here'}</h2><p>${value('tagline')||value('role')||'Your next role'}${p.field?' · '+value('field'):''}</p><div class="progress-label"><span>Profile complete</span><b>${profileCompletion().percent}%</b></div><div class="progress"><i style="width:${profileCompletion().percent}%"></i></div><div class="tags">${(p.skills||'').split(',').filter(Boolean).slice(0,8).map(s=>`<span class="tag">${esc(s.trim())}</span>`).join('')}</div><p>${value('bio')||'Your introduction and work preferences will appear here.'}</p><div class="notice">Your profile helps teams understand your experience and availability.</div><a class="outline" href="#explore">Browse paid projects →</a></section></div>${profileResumePanel()}<div class="profile-editor"><section class="panel wide-panel"><div class="setup-steps">${['About you','Work preferences','Your experience'].map((t,i)=>`<span class="${profileStep===i?'current':profileStep>i?'complete':''}"><b>${i+1}</b>${t}</span>`).join('')}</div><p class="resume-hint">Step ${profileStep+1} of 3 · Your profile</p><form id="profile-form">${profileStep===0?`<h2>First, a little about you.</h2><div class="profile-fields">${input('name','Full name','text','Your name',true)}${input('email','Email','email','you@example.com',true)}${input('education','College or university','text','Your institution',true)}${input('degree','Degree or area of study','text','e.g. Computer Science')}${input('graduation','Graduation year','number','2026')}${input('location','Location / time zone','text','e.g. Seattle · Pacific Time')}</div>`:profileStep===1?`<h2>What does your next step look like?</h2><div class="profile-fields">${select('field','Your field',Object.keys(MatchCriteria.fieldSkills))}${input('role','Target role','text','e.g. Frontend developer',true)}${select('engagement','Work you’re looking for',['Paid project / contract','Full-time role','Both projects and full-time'])}${select('availability','Weekly availability',['Under 10 hours','10–20 hours','20–30 hours','30+ hours'])}${select('workstyle','Work style',['Remote','Hybrid','On-site','Open to all'])}</div><p class="resume-hint">Preferences help describe the work you want. They do not count as evidence of a skill.</p>`:`<h2>Show what you bring.</h2>${skillSelectMarkup('profile-skills','Your skills')}${input('tagline','Tagline','text','Your professional headline')}${input('portfolio','Portfolio or work samples','url','https://...')}<p class="resume-hint">Your tagline and description fill from the first available LinkedIn or resume content. You can edit them below.</p><label class="field">Description<textarea name="bio" maxlength="2000" placeholder="What have you built? What would you like to learn?">${value('bio')}</textarea></label><div class="notice"><b>Connect your resume to your next opportunity.</b><p>Resume evidence powers compatibility scores. Profile skills are self-reported and are not substituted for resume evidence.</p><a class="text-link" href="#resume" onclick="saveProfileDraft()">Review your saved resume →</a></div>`}<p id="profile-error" class="review-error" role="alert"></p><div class="resume-actions">${profileStep?'<button type="button" class="outline" onclick="previousProfileStep()">← Back</button>':''}<button class="primary">${profileStep<2?'Save & continue →':'Save profile & find work ↗'}</button></div></form></section></div>`+(typeof Account!=='undefined'?accountPanel():'')}
function profileInitials(name){return esc((name||'You').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase())}
function saveProfileDraft(){if(typeof requireAccount==='function'&&!requireAccount())return;const form=$('#profile-form');if(!form)return;const p=graduateProfile();for(const[k,v]of new FormData(form))p[k]=String(v).trim();workspaceLocal.setItem('proof-profile',JSON.stringify(p));for(const k of ['name','education','portfolio','bio'])if(p[k])workspaceLocal.setItem('lp-'+k,p[k]);return p}
function previousProfileStep(){saveProfileDraft();profileStep=Math.max(0,profileStep-1);render()}
function bindProfile(){$('#review-resume').oninput=()=>setMarketplaceResume($('#review-resume').value);$('#profile-resume-file').onchange=e=>readResumeFile(e.target.files[0]);if(profileStep===2){bindSkillSelect('profile-skills',graduateProfile().skills||'');}$('#profile-form').onsubmit=async e=>{e.preventDefault();if(profileStep===2&&!$('#profile-skills-value').value){$('#profile-error').textContent='Select at least one skill from the suggestions.';return}const p=saveProfileDraft();if(p.graduation&&(!/^\d{4}$/.test(p.graduation)||+p.graduation<1950||+p.graduation>2100)){$('#profile-error').textContent='Use a valid four-digit graduation year.';return}if(typeof saveWorkspace==='function'){try{await saveWorkspace()}catch{return}}if(profileStep<2){profileStep++;render();window.scrollTo(0,0)}else{toast('Profile updated');const pending=Number(workspaceSession.getItem('proof-application-return'));workspaceSession.removeItem('proof-application-return');if(pending){location.hash='project/'+pending;apply(pending)}else location.hash='explore'}}}
function refreshProfileIdentity(){if(typeof Account!=='undefined'&&!Account.user)return;if(typeof isOrganizationAccount==='function'&&isOrganizationAccount()){const name=Organization.profile?.name||Account.user.user_metadata?.organization_setup?.organization_name||'Your organization';document.querySelectorAll('.avatar').forEach(el=>el.textContent=profileInitials(name));const account=$('.account');if(account){account.href='#settings';account.querySelector('b').textContent=name;account.querySelector('small').textContent='Organization account'}return}const p=graduateProfile();document.querySelectorAll('.avatar').forEach(el=>{if(!el.querySelector('img[data-profile-photo]'))el.textContent=profileInitials(p.name)});const account=$('.account');if(account){account.querySelector('b').textContent=p.name||'Set up your profile';account.querySelector('small').textContent=p.graduation?'Class of '+p.graduation:'Graduate workspace'}if(typeof paintProfilePhotos==='function')paintProfilePhotos()}

function profileResumePanel(){
const hasResume=Boolean(savedResumeFile()||(workspaceSession.getItem('proof-resume')||'').trim());
return `<section class="panel wide-panel profile-resume-upload" id="profile-resume"><h2>Your resume</h2><p>Upload once. This account resume is used for matching, skills, recommendations, and new applications across Nextwork.</p>${savedResumeHTML(true)}${hasResume?'<button type="button" class="outline" onclick="fillSavedResumeProfile()">Fill missing profile details</button>':''}${!hasResume?'<p>No resume added yet.</p><button type="button" class="primary" onclick="chooseProfileResume()">Upload resume</button>':''}<input id="profile-resume-file" type="file" accept=".pdf,.docx,.txt" aria-label="Upload your resume" hidden><p id="file-status" role="status" class="resume-hint">PDF, DOCX, or TXT · up to 5 MB · Saved privately and processed on upload.</p><details><summary>View or edit resume text</summary><label class="field">Resume text<textarea id="review-resume" maxlength="30000" placeholder="Upload a resume or paste its text here…">${esc(workspaceSession.getItem('proof-resume')||'')}</textarea></label></details><a class="text-link" href="#resume" onclick="saveProfileDraft()">Review this resume →</a></section>`;
}
function chooseProfileResume(){saveProfileDraft();$('#profile-resume-file').click();}

async function fillSavedResumeProfile(){
if(!requireAccount())return;
saveProfileDraft();
const filled=fillResumeProfile(workspaceSession.getItem('proof-resume')||'');
try{await saveWorkspace();render();toast(filled.length?'Filled '+filled.length+' empty profile fields. Review your details.':'Your existing details were kept. No additional details could be extracted.');}catch{toast('Could not save your profile details. Please try again.');}
}
